function main({response}){
    var flag = false;
    var jwt = "";
    var errorMsg = "";

    try {
        var dataJson = JSON.parse(response);
        if(dataJson.result && dataJson.code == 200) {
            jwt = dataJson.data;
            flag = true;
        } else {
            errorMsg = "获取盖亚JWT权限失败，message=" + dataJson.message;
            flag = false;
        }
    } catch(e) {
        flag = false;
        errorMsg = "获取盖亚JWT权限失败，JSON格式错误，json=" + response;
    }

    return {
        flag: flag,
        jwt: jwt,
        errorMsg: errorMsg
    }

}

function main({ data1 }) {
  if (data1 === undefined) {
    throw new Error('data1 is required');
  }

  // 此时 data1 应该已经是对象，不是字符串
  const data = data1;

  // 安全访问 data.details.employeeData
  if (!data || typeof data !== 'object' || !data.details || !Array.isArray(data.details.employeeData) || data.details.employeeData.length === 0) {
    throw new Error('No employee data');
  }

  const employeeDetailData = data.details.employeeData[0].employeeDetailData;
  if (!Array.isArray(employeeDetailData)) {
    throw new Error('employeeDetailData is not an array');
  }

  // 过滤有效班次（shiftName 不为 null/undefined）
  const validShifts = employeeDetailData.filter(day => day.shiftName != null);

  if (validShifts.length === 0) {
    throw new Error('No valid shifts found');
  }

  const firstDay = validShifts[0];
  const lastDay = validShifts[validShifts.length - 1];

  // 安全获取用餐开始时间
  function getMealBegin(day) {
    if (day.restTime && typeof day.restTime === 'object' && !Array.isArray(day.restTime)) {
      return day.middleTime;
    }
    if (Array.isArray(day.restTime) && day.restTime.length > 0 && day.restTime[0] != null) {
      if (day.restTime[0].mealBeginTime != null) {
        return day.restTime[0].mealBeginTime;
      }
    }
    return day.middleTime;
  }

  function getMealEnd(day) {
    if (day.restTime && typeof day.restTime === 'object' && !Array.isArray(day.restTime)) {
      return day.middleTime;
    }
    if (Array.isArray(day.restTime) && day.restTime.length > 0 && day.restTime[0] != null) {
      if (day.restTime[0].mealEndtime != null) {
        return day.restTime[0].mealEndtime;
      }
    }
    return day.middleTime;
  }

  // 辅助函数：安全转字符串
  function getString(val) {
    return val != null ? String(val) : '';
  }

  return {
    firstDayStartTime: getString(firstDay.startTime),
    firstDayEndTime: getString(firstDay.endTime),
    firstDayMealBeginTime: getString(getMealBegin(firstDay)),
    firstDayMealEndTime: getString(getMealEnd(firstDay)),

    lastDayStartTime: getString(lastDay.startTime),
    lastDayEndTime: getString(lastDay.endTime),
    lastDayMealBeginTime: getString(getMealBegin(lastDay)),
    lastDayMealEndTime: getString(getMealEnd(lastDay))
  };
}

