function formatDate(dateString) {
    // 使用正则表达式匹配不同的日期格式
    const regex = /^(\d{4})[-/](\d{1,2})[-/](\d{1,2})$/;
    const match = dateString.match(regex);

    if (!match) {
        throw new Error(`Invalid date format: ${dateString}`);
    }

    const year = parseInt(match[1], 10);
    const month = parseInt(match[2], 10);
    const day = parseInt(match[3], 10);

    // 创建一个Date对象，并检查其合法性
    const date = new Date(year, month - 1, day);
    if (date.getFullYear() !== year || date.getMonth() !== month - 1 || date.getDate() !== day) {
        throw new Error(`Invalid date: ${dateString}`);
    }

    // 返回格式化的日期字符串
    return `${year}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
}

function main({data1, data2}) {
    try {
        const formattedData1 = formatDate(data1);
        const formattedData2 = formatDate(data2);

        return {
            result: formattedData1,
            data2: formattedData2
        };
    } catch (error) {
        throw new Error(`Error formatting dates: ${error.message}`);
    }
}

// 示例用法
try {
    console.log(main({data1: "2025-5-1", data2: "2025-12-31"})); // 输出: { result: '2025-05-01', data2: '2025-12-31' }
    console.log(main({data1: "2025/5/1", data2: "2025/12/31"})); // 输出: { result: '2025-05-01', data2: '2025-12-31' }
    console.log(main({data1: "2025-02-30", data2: "2025-12-31"})); // 抛出错误: Invalid date: 2025-02-30
} catch (error) {
    console.error(error.message);
}

function main({ data1, data2 }) {
  const startDate = new Date(data1);
  const endDate = new Date(data2);

  // 验证日期是否有效
  if (isNaN(startDate.getTime()) || isNaN(endDate.getTime())) {
    throw new Error("Invalid date format provided.");
  }

  // 确保 startDate <= endDate
  if (startDate > endDate) {
    throw new Error("Start date must be less than or equal to end date.");
  }

  // 检查是否超过一年（365天）
  const diffInDays = (endDate - startDate) / (1000 * 60 * 60 * 24);
  if (diffInDays > 365) {
    return {
      result: "日期间隔过长"
    };
  }

  // 辅助函数：格式化日期为 YYYY-MM-DD
  function formatDate(date) {
    const y = date.getFullYear();
    const m = String(date.getMonth() + 1).padStart(2, '0');
    const d = String(date.getDate()).padStart(2, '0');
    return `${y}-${m}-${d}`;
  }

  const d1 = startDate;
  const d2 = new Date(startDate);
  d2.setDate(d1.getDate() + 5); // data1 + 5天

  const d3 = new Date(endDate);
  d3.setDate(endDate.getDate() - 5); // data2 - 5天

  const d4 = endDate;

  // 注意：即使加减后跨越月份或年份，Date 对象会自动处理（如 2025-10-30 + 5天 → 2025-11-04）

  return {
    var1: formatDate(d1),
    var2: formatDate(d2),
    var3: formatDate(d3),
    var4: formatDate(d4)
  };
}

